order, seen = [], {}
def num(m):
    k = m.group(1)
    if k not in seen:
        seen[k] = len(order) + 1; order.append(k)
    return '[%d]' % seen[k]
body = '\n\n'.join(re.sub(r'\{([A-Z0-9]+)\}', num, p) for p in BODY)
unused = [k for k in NOTES if k not in seen]
assert not unused, 'notes never cited: %s' % unused
notes = [{'number': str(i + 1), 'key': k, 'note': NOTES[k]} for i, k in enumerate(order)]

own = body + ''.join(HOLDING_NOTES.values())
