for banned in ('RedState', 'Red State', 'Daily Mail', 'Mail Media', 'Salem', 'Van Laar', 'Heslep', 'Messina', 'Kelly', 'nude', 'naked'):
    for n in notes:
        assert banned.lower() not in n['note'].lower(), '%s in note %s' % (banned, n['number'])
    assert banned.lower() not in own.lower(), '%s in the text' % banned

